Add this test to the test file `RedBlackTree.t.sol`

```solidity
    function testFuzz_GetNextBiggestAndSmallest(uint256[] memory values) public {
        // Return early if the values array is empty
        if (values.length == 0) return;
        // Bound the number of values to a reasonable range
        uint256 numValues = bound(values.length, 1, 100);
        // Insert unique values into the tree
        uint256 insertedCount = 0;
        for (uint256 i = 0; i < numValues; i++) {
            uint256 value = bound(values[i], 1, type(uint256).max - 1); // Avoid inserting NULL (0)
            if (!tree.contains(value)) {
                tree.insert(value);
                insertedCount++;
            }
        }

        // Handle the case where no unique values were inserted
        if (insertedCount == 0) return;

        // Get the highest value from the tree
        uint256 highestValue = tree.maximum();

        // Test that getNextBiggest for the highest value returns MIN
        uint256 nextBiggest = tree.getNextBiggest(highestValue);
        assertEq(nextBiggest, MIN, "getNextBiggest(max) should return MIN");

        // Test that getNextSmallest for the highest value returns the second highest value (if it exists)
        if (insertedCount > 1) {
            uint256 nextSmallest = tree.getNextSmallest(highestValue);
            assertTrue(nextSmallest < highestValue, "Next smallest should be less than the highest value");
            // Verify that going back up from the next smallest value returns the highest value
            assertEq(
                tree.getNextBiggest(nextSmallest),
                highestValue,
                "getNextBiggest(secondHighest) should return highest"
            );
        } else {
            // If there's only one element, getNextSmallest should return MAX
            uint256 nextSmallest = tree.getNextSmallest(highestValue);
            assertEq(nextSmallest, MAX, "getNextSmallest(single element) should return MAX");
        }
    }
 ```

