}

// --- MOCK TOKEN ---
contract MockToken is ERC20 {
    constructor() ERC20("Mock", "MCK") { _mint(msg.sender, 1000 ether); }
}

// --- TEST DE DOS ---
contract DoSVaultUnregisterTest is Test {
    ShareTokenUpgradeable shareToken;
    address owner = address(0x1);
    address attacker = address(0xBAD);

    address[] public assets;
    address[] public vaults;

    function setUp() public {
        vm.startPrank(owner);
        ShareTokenUpgradeable implementation = new ShareTokenUpgradeable();
        bytes memory initData = abi.encodeWithSelector(
            ShareTokenUpgradeable.initialize.selector, "Share Token", "SHARE", owner
        );
