// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {Test} from "forge-std/Test.sol";

/**
 * @title RecoveryModuleSilentFailure PoC
 * @notice Demonstrates SR-M-02: Silent Failure of Access Recovery due to Ignored Return Value
 * 
 * VULNERABILITY:
 * Line 285 in RecoveryModule.sol ignores execTransactionFromModule return value:
 * ```
 * IMultisig(multisig).execTransactionFromModule(...);  // Return value ignored!
 * emit AccessRecovered(msg.sender, serviceId);
 * ```
 * 
 * Gnosis Safe 1.3.0 returns false on internal failure instead of reverting.
 * The AccessRecovered event is emitted even if recovery actually failed.
 */

/// @dev Mock Multisig that mimics Gnosis Safe 1.3.0 behavior
contract MockMultisig {
    address[] public owners;
    bool public shouldFail;

    constructor(address[] memory _owners) { owners = _owners; }

    function setShouldFail(bool _fail) external { shouldFail = _fail; }
    function getOwners() external view returns (address[] memory) { return owners; }

    /// @dev Mimics Gnosis Safe: returns false on failure instead of reverting
    function execTransactionFromModule(address, uint256, bytes memory, uint8) external returns (bool) {
        if (shouldFail) return false;  // Safe returns false, doesn't revert
        return true;
    }
}

/// @dev Mirrors vulnerable RecoveryModule.recoverAccess() logic
contract VulnerableRecoveryModule {
    event AccessRecovered(address indexed owner, uint256 serviceId);

    address public multiSend;
    uint256 internal _locked = 1;

    constructor(address _multiSend) { multiSend = _multiSend; }

    function recoverAccess(address multisig, uint256 serviceId) external {
        require(_locked == 1, "ReentrancyGuard");
        _locked = 2;

        bytes memory payload = abi.encodeWithSignature("multiSend(bytes)", "");

        // VULNERABILITY: Return value not checked!
        // Gnosis Safe returns false on failure, but we ignore it
        MockMultisig(multisig).execTransactionFromModule(multiSend, 0, payload, 1);

        // Event emitted regardless of whether recovery actually succeeded
        emit AccessRecovered(msg.sender, serviceId);

        _locked = 1;
    }
}

contract RecoveryModuleSilentFailureTest is Test {
    VulnerableRecoveryModule recoveryModule;
    MockMultisig multisig;

    address serviceOwner;
    address agentInstance1;
    address agentInstance2;

    event AccessRecovered(address indexed owner, uint256 serviceId);

    function setUp() public {
        serviceOwner = makeAddr("serviceOwner");
        agentInstance1 = makeAddr("agentInstance1");
        agentInstance2 = makeAddr("agentInstance2");

        address[] memory owners = new address[](2);
        owners[0] = agentInstance1;
        owners[1] = agentInstance2;

        multisig = new MockMultisig(owners);
        recoveryModule = new VulnerableRecoveryModule(makeAddr("multiSend"));
    }

    /**
     * @notice PROOF: recoverAccess() emits event even when recovery fails
     * 
     * Attack scenario:
     * 1. Service owner's agents are compromised/lost
     * 2. Owner calls recoverAccess() to regain control
     * 3. execTransactionFromModule fails internally (returns false)
     * 4. recoverAccess() ignores the failure, emits AccessRecovered
     * 5. Owner believes they recovered access
     * 6. Reality: Compromised agents STILL control the multisig
     * 7. Attacker drains funds while owner thinks they're safe
     */
    function test_VulnerableRecovery_EmitsEventDespiteFailure() public {
        uint256 serviceId = 1;

        // Simulate execTransactionFromModule failing (returns false)
        // This can happen due to: invalid swapOwner call, gas issues, etc.
        multisig.setShouldFail(true);

        // PROOF 1: Multisig owners are agent instances (not service owner)
        address[] memory ownersBefore = multisig.getOwners();
        assertEq(ownersBefore[0], agentInstance1);
        assertEq(ownersBefore[1], agentInstance2);

        // PROOF 2: Event IS emitted despite failure
        vm.expectEmit(true, false, false, true);
        emit AccessRecovered(serviceOwner, serviceId);

        // PROOF 3: recoverAccess() does NOT revert
        vm.prank(serviceOwner);
        recoveryModule.recoverAccess(address(multisig), serviceId);

        // PROOF 4: Owners are UNCHANGED - recovery silently failed
        // Service owner thinks they recovered, but agents still control multisig
        address[] memory ownersAfter = multisig.getOwners();
        assertEq(ownersAfter[0], agentInstance1);  // Still agent, NOT service owner
        assertEq(ownersAfter[1], agentInstance2);  // Still agent, NOT service owner
    }

    /**
     * @notice Contrast: When execTransactionFromModule succeeds, event is legitimate
     */
    function test_NormalCase_RecoverySucceeds() public {
        multisig.setShouldFail(false);  // execTransactionFromModule will succeed

        vm.expectEmit(true, false, false, true);
        emit AccessRecovered(serviceOwner, 1);

        vm.prank(serviceOwner);
        recoveryModule.recoverAccess(address(multisig), 1);

        // In real scenario, owners would be swapped to service owner
    }
}

