// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {PoCTestBase} from "./PoCTestBase.t.sol";
import {ICLOB} from "contracts/clob/ICLOB.sol";
import {CLOB} from "contracts/clob/CLOB.sol";
import {Side, Order} from "contracts/clob/types/Order.sol";

contract PoC is PoCTestBase {
    function test_submissionValidity() external {
    }

    /// @notice PoC: View functions return expired orders as active, creating information asymmetry
    /// This test demonstrates that getTOB() and getOrdersPaginated() show expired orders
    /// while the matching engine correctly removes them during execution
    function test_viewFunctions_showExpiredOrders_whileMatchingEngine_removesExpiredOrders() public {
        uint32 expiryTime = uint32(block.timestamp + 1 hours);

        // Create bid order that will expire
        setupTokens(Side.BUY, users[0], 1 ether, 100 ether, true);
        vm.prank(users[0]);
        clob.postLimitOrder(users[0], ICLOB.PostLimitOrderArgs({
            amountInBase: 1 ether,
            clientOrderId: 0,
            price: 100 ether,
            cancelTimestamp: expiryTime,
            side: Side.BUY,
            limitOrderType: ICLOB.LimitOrderType.GOOD_TILL_CANCELLED
        }));

        // Verify order is visible before expiry
        (uint256 maxBid,) = clob.getTOB();
        assertEq(maxBid, 100 ether, "Bid should be visible before expiry");

        // Fast forward past expiry
        vm.warp(expiryTime + 1);

        // VULNERABILITY: View functions still show expired orders as active
        (uint256 maxBidAfterExpiry,) = clob.getTOB();
        assertEq(maxBidAfterExpiry, 100 ether, "VULNERABILITY: Expired bid still visible in getTOB()");

        // View functions show expired orders in pagination
        (Order[] memory bidOrders,) = clob.getOrdersPaginated(100 ether, Side.BUY, 10);
        assertEq(bidOrders.length, 1, "VULNERABILITY: Expired bid visible in getOrdersPaginated()");
        assertEq(bidOrders[0].cancelTimestamp, expiryTime, "Expired bid order returned");

        // But matching engine correctly handles expired orders by removing them
        // When we try to trade against the "visible" expired order, it should fail with ZeroCostTrade
        // because the matching engine removes expired orders and finds nothing to trade against
        setupTokens(Side.SELL, users[1], 1 ether, 100 ether, true);

        // This should revert with ZeroCostTrade because the matching engine removes the expired order
        // and finds no valid orders to match against, proving the discrepancy
        vm.expectRevert(abi.encodeWithSelector(CLOB.ZeroCostTrade.selector));
        vm.prank(users[1]);
        clob.postFillOrder(users[1], ICLOB.PostFillOrderArgs({
            amount: 1 ether,
            priceLimit: 100 ether, // Try to hit the "visible" but expired bid
            side: Side.SELL,
            amountIsBase: true,
            fillOrderType: ICLOB.FillOrderType.IMMEDIATE_OR_CANCEL
        }));

        // The view functions STILL show the expired order even after the matching engine processed it
        (uint256 stillVisibleBid,) = clob.getTOB();
        assertEq(stillVisibleBid, 100 ether, "VULNERABILITY: Expired bid STILL visible after matching engine ran");

        // This proves the critical information asymmetry:
        // - View functions show liquidity that doesn't exist
        // - Traders see orders they cannot actually execute against
        // - Off-chain systems get misleading market data
    }
}

