## Finding description and impact

In the `AgentTax.sol` contract, in the function `dcaSell`, there is no check for return value of  `_swapForAsset();`, the function `_swapForAsset()` returns false on fail.

This means the swap can silently fail and the function will continue without a revert.

This could cause issues, because callers may assume the swap was successful, while it was not, also it may lead to incorrect contract state.

Code snippet:
```solidity
   function dcaSell(
        uint256[] memory agentIds,
        uint256 slippage,
        uint256 maxOverride
    ) public onlyRole(EXECUTOR_ROLE) {
        require(slippage <= DENOM, "Invalid slippage");
        uint256 agentId;
        for (uint i = 0; i < agentIds.length; i++) {
            agentId = agentIds[i];

            TaxAmounts memory agentAmounts = agentTaxAmounts[agentId];
            uint256 amountToSwap = agentAmounts.amountCollected -
                agentAmounts.amountSwapped;

            if (amountToSwap > maxOverride) {
                amountToSwap = maxOverride;
            }

            uint256 minOutput = ((amountToSwap * (DENOM - slippage)) / DENOM);
            _swapForAsset(agentId, minOutput, maxOverride); // @audit-issue unchecked return, may silently fail
        }
    }
```

Same in the function `handleAgentTaxes`, where it even updates the state, leading to incorrect state if swap silently fails.

```solidity
    function handleAgentTaxes(
        uint256 agentId,
        bytes32[] memory txhashes,
        uint256[] memory amounts,
        uint256 minOutput
    ) public onlyRole(EXECUTOR_ROLE) {
        require(txhashes.length == amounts.length, "Unmatched inputs");
        TaxAmounts storage agentAmounts = agentTaxAmounts[agentId];
        uint256 totalAmount = 0;
        for (uint i = 0; i < txhashes.length; i++) {
            bytes32 txhash = txhashes[i];
            if (taxHistory[txhash].agentId > 0) {
                revert TxHashExists(txhash);
            }
            taxHistory[txhash] = TaxHistory(agentId, amounts[i]);
            totalAmount += amounts[i];
            emit TaxCollected(txhash, agentId, amounts[i]);
        }
        agentAmounts.amountCollected += totalAmount;
        _swapForAsset(agentId, minOutput, maxSwapThreshold); // @audit-issue unchecked return, may silently fail
