`test/c4-poc/ExpiredOrdersLock.t.sol` will reproduce the bug:  
* Adds an ask that expires after 1 s.  
* Warps time beyond expiry.  
* A BUY `postFillOrder()` reverts with `ZeroCostTrade`.  
* Assertions confirm the expired ask is still in the book and open-interest unchanged, proving funds are locked.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {CLOBTestBase} from "test/clob/utils/CLOBTestBase.sol";
import {ICLOB} from "contracts/clob/ICLOB.sol";
import {Side} from "contracts/clob/types/Order.sol";
import {CLOB} from "contracts/clob/CLOB.sol";
import "forge-std/console.sol";

/// @notice PoC for bug: expired orders remain stuck & funds locked if entire side expired
/// The test reproduces scenario where all asks expire, a taker tries to cross them, but
/// transaction reverts with ZeroCostTrade, leaving expired orders and funds locked.
contract ExpiredOrdersLockTest is CLOBTestBase {
    function test_ExpiredOrders_Cause_Lock() public {
        // 1. Maker posts an ask with very short expiry
        address maker = users[0];
        uint256 price = 100 ether;
        uint256 amountInBase = 1 ether;

        // Deposit base tokens for maker and post limit ask (GTC equivalent w/ short cancelTimestamp)
        setupTokens(Side.SELL, maker, amountInBase, price, true);

        ICLOB.PostLimitOrderArgs memory askArgs = ICLOB.PostLimitOrderArgs({
            amountInBase: amountInBase,
            price: price,
            cancelTimestamp: uint32(block.timestamp + 1), // expires in 1 second
            side: Side.SELL,
            clientOrderId: 0,
            limitOrderType: ICLOB.LimitOrderType.GOOD_TILL_CANCELLED
        });

        vm.prank(maker);
        clob.postLimitOrder(maker, askArgs);

        // sanity: one ask in book & base OI equals order size
        (uint256 quoteOiBefore, uint256 baseOiBefore) = clob.getOpenInterest();
        assertEq(clob.getNumAsks(), 1, "expected one ask in book");
        assertEq(baseOiBefore, amountInBase, "base OI mismatch before");

        // 2. Fast-forward beyond expiry
        vm.warp(block.timestamp + 2);

        // 3. Taker attempts to fill — should revert ZeroCostTrade due to bug
        address taker = users[1];
        uint256 takerAmountInBase = amountInBase; // try buy same size
        uint256 takerPriceLimit = price * 2; // high enough to cross

        // deposit quote tokens for taker (amount denominated in base for BUY side)
        uint256 quoteToDeposit = quoteTokenAmount(takerPriceLimit, takerAmountInBase);
        setupTokens(Side.BUY, taker, quoteToDeposit, takerPriceLimit, false);

        ICLOB.PostFillOrderArgs memory fillArgs = ICLOB.PostFillOrderArgs({
            amount: takerAmountInBase,
            priceLimit: takerPriceLimit,
            side: Side.BUY,
            amountIsBase: true,
            fillOrderType: ICLOB.FillOrderType.IMMEDIATE_OR_CANCEL
        });

        vm.startPrank(taker);
        vm.expectRevert(CLOB.ZeroCostTrade.selector);
        clob.postFillOrder(taker, fillArgs);
        vm.stopPrank();

        // 4. Book state unchanged – expired order still present, funds locked
        (uint256 quoteOiAfter, uint256 baseOiAfter) = clob.getOpenInterest();
        assertEq(clob.getNumAsks(), 1, "expired ask still stuck");
        assertEq(baseOiAfter, baseOiBefore, "base OI unchanged, funds locked");
        assertEq(quoteOiAfter, quoteOiBefore, "quote OI unchanged");
    }
}
```

