## Proof of Concept

The following test case demonstrates the vulnerability. It simulates a scenario where a user ("Alice") holds 4 legs. The protocol then lowers the `maxLegs` limit to 2. When Alice attempts to burn one position (reducing her leg count to 3), the transaction reverts, locking her funds.

Add this test to `test/foundry/core/PanopticPool.t.sol`:

```solidity
    /*//////////////////////////////////////////////////////////////
                        H-04: MAX LEGS BURN DOS TEST
    //////////////////////////////////////////////////////////////*/

    function test_H04_BurnRevertsWhenMaxLegsReduced() public {
        // 1. Initialize the pool
        _initPool(0);

        vm.startPrank(Alice);

        // 2. Prepare 4 distinct single-leg positions
        // We use 4 legs to simulate a scenario where legs > newMaxLegs (4 > 2)

        TokenId[] memory posIdList = new TokenId[](4);
        uint128[] memory positionSizes = new uint128[](4);
        int24[3][] memory tickAndSpreadLimits = new int24[3][](4);

        for (uint256 i = 0; i < 4; i++) {
            // Generate distinct OTM positions to ensure different TokenIds
            (int24 width, int24 strike) = PositionUtils.getOTMSW(
                i + 1, 
                int256(i), 
                uint24(tickSpacing),
                currentTick,
                0
            );
            populatePositionData(width, strike, 10 ** 18);

            posIdList[i] = TokenId.wrap(0).addPoolId(poolId).addLeg(
                0, 1, isWETH, 0, 0, 0, strike, width
            );
            positionSizes[i] = 10 ** 18;

            tickAndSpreadLimits[i][0] = Constants.MIN_POOL_TICK;
            tickAndSpreadLimits[i][1] = Constants.MAX_POOL_TICK;
            tickAndSpreadLimits[i][2] = int24(uint24(type(uint24).max));
        }

        // 3. Mint all positions
        // At this point, the protocol allows > 4 legs (default is usually 25 or 33)
        pp.dispatch(
            posIdList, 
            posIdList, 
            positionSizes, 
            tickAndSpreadLimits, 
            true, 
            0
        );

        assertEq(pp.numberOfLegs(Alice), 4, "Setup failed: Alice should have 4 legs");

        // 4. Simulate governance lowering maxLegs to 2
        // We achieve this by mocking the return value of RiskEngine.getRiskParameters

        (RiskParameters realParams, ) = pp.getRiskParameters(0);
        uint256 rawParams = RiskParameters.unwrap(realParams);

        // Clear the maxLegs bits (bits 121-127)
        uint256 mask = ~(uint256(0x7F) << 121);
        uint256 clearedParams = rawParams & mask;

        // Set new maxLegs = 2
        uint256 newMaxLegs = 2;
        uint256 mockedParamsInt = clearedParams | (newMaxLegs << 121);

        // Mock the call to RiskEngine
        vm.mockCall(
            address(re),
            abi.encodeWithSelector(IRiskEngine.getRiskParameters.selector),
            abi.encode(RiskParameters.wrap(mockedParamsInt))
        );

        // 5. Attempt to Burn 1 position (posIdList[0])
        // If successful, Alice should have 3 legs remaining.
        // However, since 3 > 2 (newMaxLegs), the transaction will revert.

        TokenId[] memory burnList = new TokenId[](1);
        burnList[0] = posIdList[0];

        // Set size to 0 to trigger the Burn path in dispatch()
        uint128[] memory burnSizes = new uint128[](1);
        burnSizes[0] = 0; 

        // Construct the expected final list (Alice retains positions 1, 2, 3)
        TokenId[] memory finalList = new TokenId[](3);
        finalList[0] = posIdList[1];
        finalList[1] = posIdList[2];
        finalList[2] = posIdList[3];

        int24[3][] memory burnLimits = new int24[3][](1);
        burnLimits[0][0] = Constants.MIN_POOL_TICK;
        burnLimits[0][1] = Constants.MAX_POOL_TICK;
        burnLimits[0][2] = int24(uint24(type(uint24).max));

        // 6. Expect Revert: TooManyLegsOpen
        // This confirms that reducing the leg count is blocked if the result is still above the limit.
        vm.expectRevert(Errors.TooManyLegsOpen.selector);

        pp.dispatch(
            burnList, 
            finalList, 
            burnSizes, 
            burnLimits, 
            true, 
            0
        );

        vm.stopPrank();
    }
```


